import { Navigate } from 'react-router-dom';
import classes from './Dialogs.module.css';
import DialogItem from './DialogItem/Dialogs';
import Message from './Message/Message';
import { reduxForm, Field } from 'redux-form';
import { maxLengthCreator, required } from '../../utils/validators';
import { TextArea } from '../common/FromsControls';

let maxLength50 = maxLengthCreator(50);
const Dialogs = (props) => {

    let dialogsElements = props.dialogs.map((dialog) => <DialogItem name={dialog.name} key={dialog.id} id={dialog.id} />);
    let messagesElements = props.messages.map((message) => <Message message={message.message} key={message.id} id={message.id} />);
    //let newMessageText = props.newMessageText;

    let addNewMessage = (values) => {
        props.addMessage(values.newMessageText);
    }

    if (!props.isAuth) return <Navigate to={'/login'} />


    return (
        <div className={classes.dialogs}>
            <div className={classes.dialogsItems}>
                {dialogsElements}
            </div>
            <div className={classes.messages}>
                {messagesElements}
                <AddMessageFormRedux onSubmit={addNewMessage}/>



            </div>

        </div>

    );
}

const AddMessageForm = (props) => {

    return <form onSubmit={props.handleSubmit}>
        <div>
            <div className={classes.writeMessage}>
                <Field component={TextArea} name={'newMessageText'} 
                placeholder={'Enter your message'} validate={[required,maxLength50]}/>
            </div>
        </div>
        <div className={classes.writeMessage}>
            <button>Add message</button>
        </div>
    </form>
}

const AddMessageFormRedux = reduxForm({ form: 'dialogAddMessageForm' })(AddMessageForm);


    export default Dialogs;